import React, { useState, useEffect } from 'react';
import QuestionItem from '../components/QuestionItem';
import Navbar from '../components/Navbar';

const generateId = () => Date.now() + Math.random();

const BuilderPage = () => {
  const [questions, setQuestions] = useState(() => {
    const saved = localStorage.getItem('questions');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('questions', JSON.stringify(questions));
  }, [questions]);

  // Add Parent Question
  const addParentQuestion = () => {
    const newQuestion = {
      id: generateId(),
      text: '',
      type: 'Short Answer',
      answer: '',
      userAnswer: '',
      children: [],
    };

    setQuestions([...questions, newQuestion]);
  };

  // Update Question
  const updateQuestion = (id, updatedData, items = questions) => {
    return items.map((item) => {
      if (item.id === id) {
        return { ...item, ...updatedData };
      }

      return {
        ...item,
        children: updateQuestion(id, updatedData, item.children),
      };
    });
  };

  const handleUpdate = (id, data) => {
    setQuestions((prev) => updateQuestion(id, data, prev));
  };

  // Delete Question
  const deleteQuestion = (id, items = questions) => {
    return items
      .filter((item) => item.id !== id)
      .map((item) => ({
        ...item,
        children: deleteQuestion(id, item.children),
      }));
  };

  const handleDelete = (id) => {
    setQuestions((prev) => deleteQuestion(id, prev));
  };

  // Add Child Question
  const addChildQuestion = (parentId, items = questions) => {
    return items.map((item) => {
      if (item.id === parentId) {
        const child = {
          id: generateId(),
          text: '',
          type: 'Short Answer',
          answer: '',
          userAnswer: '',
          children: [],
        };

        return {
          ...item,
          children: [...item.children, child],
        };
      }

      return {
        ...item,
        children: addChildQuestion(parentId, item.children),
      };
    });
  };

  const handleAddChild = (parentId) => {
    setQuestions((prev) => addChildQuestion(parentId, prev));
  };

  return (
    <div className="min-h-screen bg-gray-100 p-6">

      <Navbar />

      <div className="bg-white shadow-lg rounded-2xl p-6">

        <div className="flex justify-between items-center mb-6">

          <h1 className="text-3xl font-bold text-gray-800">
            Edit 
          </h1>

          <button
            onClick={addParentQuestion}
            className="bg-green-500 hover:bg-green-600 text-white px-5 py-2 rounded-lg transition"
          >
            Add Question
          </button>

        </div>

        {questions.length === 0 ? (
          <div className="text-center text-gray-500 py-10">
            No questions added yet.
          </div>
        ) : (
          questions.map((question, index) => (
            <QuestionItem
              key={question.id}
              question={question}
              numbering={`Q${index + 1}`}
              onUpdate={handleUpdate}
              onDelete={handleDelete}
              onAddChild={handleAddChild}
            />
          ))
        )}

      </div>

    </div>
  );
};

export default BuilderPage;
